// Módulo de Feed Contextual

// src/core/feed/feed.module.ts
// Módulo do FEED PLUGIN SYSTEM
// 🔴 BLINDAGEM: Feed = orquestrador visual, Domínios = motores
// 🔴 BLINDAGEM: Feed não executa ações de domínio

import { FastifyPluginAsync } from 'fastify';
import feedRoutes from './feed.routes';
import feedPluginRoutes from './feed-plugin.routes';

const feedModule: FastifyPluginAsync = async (fastify) => {
  // Rotas do feed existente
  await fastify.register(feedRoutes);
  
  // Rotas do plugin system
  await fastify.register(feedPluginRoutes, { prefix: '/plugin' });
};

export default feedModule;
export const feedContextualModule = feedModule;



























